use std::sync::atomic::{AtomicPtr, Ordering};
use std::sync::Arc;

struct State { version: u64, balances: Vec<i64> }

fn transfer(head: &AtomicPtr<State>, from: usize, to: usize, amt: i64) -> bool {
    loop {
        // SAFETY: the pointer was published by a previous store and is never freed
        // while a reader holds it (epoch/deferred reclamation required).
        let cur = unsafe { &*head.load(Ordering::Acquire) };
        let mut next = State { version: cur.version, balances: cur.balances.clone() };
        if next.balances[from] < amt { return false }
        next.balances[from] -= amt; next.balances[to] += amt; next.version += 1;

        // whole block replays if anyone committed first
        match head.compare_exchange(cur as *const State as *mut State,
                                    Box::into_raw(Box::new(next)),
                                    Ordering::AcqRel, Ordering::Acquire) {
            Ok(_) => return true,
            Err(_) => continue,      // lost the race: re-read and recompute
        }
    }
}
